import math

def rotate(p, degrees):
    r = math.radians(degrees)
    return (p[0] * math.cos(r) - p[1] * math.sin(r), p[0] * math.sin(r) + p[1] * math.cos(r))

print([round(x, 2) for x in rotate((0.707, 0.707), -45)])  # [1.0, 0.0]

import math

def rotate(p, degrees):
    r = math.radians(degrees)
    return (p[0] * math.cos(r) - p[1] * math.sin(r), p[0] * math.sin(r) + p[1] * math.cos(r))

print([round(x, 2) for x in rotate((3.0, 0.0), 45)])  # [2.12, 2.12]
